import React from 'react';
import './Bar.css';

const Bar = ({
  width,
  height,
  val,
  stateA,
  stateB,
  stateC,
  stateD,
  sorted,
  style
}) => {

  let classNames = 'Bar';
  if (sorted) classNames += ' Bar_sorted';
  if (stateD) classNames += ' Bar_stateD';
  if (stateC) classNames += ' Bar_stateC';
  if (stateB) classNames += ' Bar_stateB';
  if (stateA) classNames += ' Bar_stateA';
  //console.log('val: ', val, 'stateA: ', stateA, 'stateB: ', stateB, 'stateC: ', stateC, 'stateD: ', stateD, 'classNames: ', classNames);

  let BarStyle = { ...style, width: `${width}%`, height: `${height}%` };
  if (stateA || stateB || stateC || stateD) {
    BarStyle['marginRight'] = `${0.3 * width}%`;
    BarStyle['marginLeft'] = `${0.3 * width}% `;
  }

  return (
    <div style={BarStyle} className={classNames}>
      <span className="Bar__Text">{val}</span>
    </div>
  );
};

export default Bar;
