import React from 'react';
import { Tabs } from 'antd';
import SortInfo from "../SortInfo/SortInfo";
import ImplementationTabs from "../ImplementationTabs/ImplementationTabs";
import './SortInfoTabs.css';
import TryYourselfTab from "../TryYourselfTab/TryYourselfTab";
import SortVisualizer from "../../main/SortVisualizer/SortVisualizer";

const SortInfoTabs = ({desc, cCode, cppCode, javaCode, jsCode, pythonCode, array, trace, colorKey, sortKey, onGenerateRandomArray}) => {
    console.log('SortInfoTabs trace: ', trace);
    const onChange = (key) => {
        console.log('SortInfoTabs onChange key:', key);
    };

    const items = [
        {
            key: '1',
            label: 'Description',
            children: <SortInfo {...desc} />,
        },
        {
            key: '2',
            label: 'Implementation',
            children: <ImplementationTabs cCode={cCode} cppCode={cppCode} jsCode={jsCode} javaCode={javaCode} pythonCode={pythonCode} /> ,
        },
        {
            key: '3',
            label: 'Sort Visualizer',
            children: <SortVisualizer array={array} trace={trace} colorKey={colorKey} desc={desc} /> ,
        },
        {
            key: '4',
            label: 'Try Yourself',
            children: <TryYourselfTab array={array} trace={trace} sortKey={sortKey} onGenerateRandomArray={onGenerateRandomArray}/> ,
        },
    ];
    return (
        <Tabs defaultActiveKey="1" items={items} onChange = {onChange} />
    );
}
export default SortInfoTabs;


