import React, { Fragment } from 'react';
import PropTypes from 'prop-types';
import './AppControls.css';

import { Button } from "antd";
import { Select } from "antd";
import { Switch } from "antd";

const AppControls = ({
  onGenerateRandomArray,
  arraySize,
  onArraySizeChange,
  onToggleDarkMode,
  darkMode
}) => {
  return (
    <Fragment>
        <div className="TopBar__Section">
            <div className="AppControls__Size">
                <span>Array Size</span>
                <Select
                    defaultValue={String(arraySize)}
                    style={{
                        width: 70,
                    }}
                    onChange={onArraySizeChange}
                    options={[
                        {
                            value: '5',
                            label: '5',
                        },
                        {
                            value: '6',
                            label: '6',
                        },
                        {
                            value: '8',
                            label: '8',
                        },
                        {
                            value: '10',
                            label: '10',
                        },

                    ]}
                />

            </div>

            <Button onClick={onGenerateRandomArray}>Generate</Button>

            <span>Dark Mode</span>
            <Switch defaultChecked onChange={onToggleDarkMode} checked={darkMode}/>
        </div>

    </Fragment>
  );
};

AppControls.propTypes = {
    onGenerateRandomArray: PropTypes.func.isRequired,
    arraySize: PropTypes.number,
    onArraySizeChange: PropTypes.func.isRequired,
    onToggleDarkMode: PropTypes.func.isRequired,
    darkMode: PropTypes.bool
};

export default AppControls;
