import React, {useEffect, useState} from 'react';
import './TryInput.css';
import { InputNumber, Button } from 'antd';

const TryInput = ({round, answerArray, sortedIndices, displayIndices, onSubmit, onGenerateRandomArray}) => {
    const [inputArray, setInputArray] = useState([]);
    const [errors, setErrors] = useState([])

    console.log('in TryInput, answerArray: ', answerArray)
    useEffect(() => {
        const initialInput = answerArray.map((answer, index) => (displayIndices.includes(index)? answer : null));
        setInputArray(initialInput);
        console.log('initialInput:',initialInput, 'inputArray:',inputArray);
    }, [answerArray]);


    const onChange = (index, value) => {
        console.log('changed', value);
        const newArray = [...inputArray];
        newArray[index] = value;
        setInputArray(newArray);
        const newErrors = [...errors];
        newErrors[index] = !answerArray.includes(value);
        setErrors(newErrors);
    };

    const haveEmptyInput = () => {
        return inputArray.findIndex(item => item == null) >=0 ;
    }

    const getErrorMessages = () => {
        let errorIndices = '';
        for( let i=0 ; i< inputArray.length; i++) {
            if (inputArray[i]!=null && errors[i]) {
                if (!errorIndices)
                {
                    errorIndices += '' + i;
                }
                else {
                    errorIndices += ',' + i;
                }
            }
        }
        if (errorIndices) {
            return 'The input on index: ' + errorIndices + ' is invalid!';
        }
        if (haveEmptyInput()) {
            return 'Please enter your inputs!';
        }
        return '';
    }

    const hasError = () => {
        return getErrorMessages()!== '';
    }

    return (
        <>
            <div className={"try-input"}>
                <label>Round{round}</label>
                {
                    answerArray.map((answer, index) => (
                        displayIndices.includes(index) ? <span className={"sorted"}>{answer}</span> :
                            <InputNumber min={0} max={100} onChange={(e) => onChange(index, e)}
                                         value={inputArray[index]} status={errors[index]? "error": "" } />))
                }

                <Button type="primary" onClick={() => onSubmit(inputArray, answerArray, sortedIndices)}
                        disabled={round > answerArray.length || hasError()}>Submit</Button>
                {
                    round > answerArray.length ?
                        <Button type="primary" onClick={onGenerateRandomArray}>Try Again</Button> : null
                }
            </div>
            <div className={"error-section"}>
                {
                    hasError() ? <span className={"error-message"}>{getErrorMessages()}</span> : null
                }
            </div>
        </>

    );

}

export default TryInput;