import React, {useEffect, useState} from 'react';
import './TryYourselfTab.css';
import ArrayInfo from "../ArrayInfo/ArrayInfo";
import TryStep from "../TryStep/TryStep";
import TryInput from "../TryInput/TryInput";
import {Button} from "antd";
import {SortKey} from "../../../data/SortKey";

const TryYourselfTab = ({array, trace, sortKey, onGenerateRandomArray}) => {
    const [trySteps, setTrySteps] = useState([]);
    const [round, setRound] = useState(1);

    console.log('TryYourselfTab array:', array, 'trace:', trace);

    useEffect(() => {
        setTrySteps([]);
        setRound(1);
    }, [array, trace]);

    const findCurrentSortStep = () => {
        if (sortKey === SortKey.INSERTION) {
            return trace.find(item => item.groupC.length === round);
        } else if (sortKey === SortKey.MERGE) {
            const mergeSteps = getMergeSortSteps();
            return round > mergeSteps.length ? null: mergeSteps[round -1];
        }
        else {
            return trace.find(item => item.sortedIndices.length === round);
        }
    }

    const getAnswerArray = () => {
        const step = findCurrentSortStep();
        console.log('getAnswerArray, step:', step);
        return step ? step.array: [];
    }

    const getSortedIndices = () => {
        const step = findCurrentSortStep();
        return step ? step.sortedIndices: [];
    }

    const getGroupC = () => {
        const step = findCurrentSortStep();
        return step ? step.groupC: [];
    }

    const getDisplayIndices = () => {
        if (sortKey === SortKey.INSERTION || sortKey === SortKey.MERGE) {
            return getGroupC();
        } else {
            return getSortedIndices();
        }
    }

    const isSortDone = () => {
        if (sortKey === SortKey.MERGE) {
            return round > getMergeSortSteps().length;
        } else {
            return round > array.length;
        }
    }

    const getMergeSortSteps = () => {
        return trace.filter(step => step.groupC && step.groupC.length >0);
    }

    const handleSubmit = (newInputArray, newAnswerArray, sortedIndices) => {
        const newTrySteps = [...trySteps];
        newTrySteps.push({inputArray:newInputArray, answerArray: newAnswerArray, sortedIndices});
        setTrySteps(newTrySteps);
        setRound(round + 1);
    }

    return (
        <div className={"try-yourself"}>
            <div className={"original-array"}>
                <ArrayInfo array={array} label={"Original Array:"} sortedIndices={[]}/>
                <span className={"regen-button"}><Button type="primary" onClick={onGenerateRandomArray} >Regenerate</Button></span>
            </div>
            <div className={"try-steps"}>
                {
                    trySteps.map((step, index) => (
                        <TryStep round={index +1} inputArray={step.inputArray} answerArray={step.answerArray} sortedIndices={step.sortedIndices}/>
                    ))
                }
                {
                    (isSortDone()) ? <div className={"done-message"}>Sorting is done!</div>: null
                }
            </div>
            <div className={"try-inputs"}>
                <TryInput round={round} answerArray={getAnswerArray()} sortedIndices={getSortedIndices()} displayIndices={getDisplayIndices()} onSubmit={handleSubmit} onGenerateRandomArray={onGenerateRandomArray}/>

            </div>
        </div>
    );
}
export default TryYourselfTab;

