import React from 'react';
import './TryStep.css';
import isEqual from 'lodash/isEqual';
import ArrayInfo from "../ArrayInfo/ArrayInfo";
import {
    CheckOutlined,
    CloseOutlined
} from '@ant-design/icons';

const TryStep = ({round, inputArray, answerArray, sortedIndices}) => {

    const isAnswerCorrect = () => isEqual(inputArray, answerArray);

    return (
        <div className={"try-step"}>
            <span>Round{round}</span>
            <div className={"array-compare"}>
                <div>
                    <ArrayInfo array={inputArray} label={"You:"} sortedIndices={sortedIndices}/>
                    {
                        isAnswerCorrect() ?
                            <span className={"array-compare__correct"}><CheckOutlined /></span> :
                            <span className={"array-compare__incorrect"}><CloseOutlined /></span>
                    }
                </div>
                <ArrayInfo array={answerArray} label={"Answer:"} sortedIndices={sortedIndices}/>
            </div>
        </div>
    )

}

export default TryStep;