import React from 'react';
import {
  swap,
  newTrace,
  addToTrace,
  lastSorted,
  createKey
} from './helpers';

const BubbleSort = (nums) => {
  // Set up code for tracing the algorithm
  const trace = newTrace(nums);

  // Sorting Algorithm with trace capture
  for (let i = 0; i < nums.length; i++) {
    for (let j = 0; j < nums.length - i - 1; j++) {
      // Visualize: Comparing A[j] and A[j + 1]
      addToTrace(trace, nums, lastSorted(trace), [j, j + 1]);
      if (nums[j] > nums[j + 1]) {
        swap(nums, j, j + 1);
        // Visualize: Swap A[j] and A[j + 1]
        addToTrace(trace, nums, lastSorted(trace), [], [j, j + 1]);
      }
    }

    // Visualize: final value is sorted
    addToTrace(trace, nums, [
      ...lastSorted(trace),
      nums.length - 1 - i
    ]);
  }

  return trace;
};

export const BubbleSortKey = createKey('Compare', 'Swap');
export const BubbleSortDesc = {
  title: 'Bubble Sort',
  description: (
      <p>
        <a
            href="https://en.wikipedia.org/wiki/Bubble_sort"
            target="_blank"
            rel="noopener noreferrer"
        >
          Bubble Sort
        </a>{' '}
        is a comparison-based sorting algorithm that repeatedly swaps adjacent elements if they are in the wrong order.
        This process continues until the array is sorted.<br/>
        <b>Algorithm Steps:</b>
        <ol>
          <li>
            Compare adjacent elements and swap them if they are in the wrong order.
          </li>
          <li>
            Repeat this process for the entire array.
          </li>
          <li>
            After each full pass, the largest unsorted element moves to its correct position.
          </li>
          <li>
            Continue until no swaps are needed (meaning the array is sorted).
          </li>
        </ol>
      </p>
  ),
  worstCase: (
      <span>
      O(n<sup>2</sup>)(if the array is in reverse order)
    </span>
  ),
  avgCase: (
      <span>
      O(n<sup>2</sup>)
    </span>
  ),
  bestCase: <span>O(n)(if already sorted, with an optimized version)</span>,
  space: <span>O(1)(in-place sorting)</span>
};
export default BubbleSort;
