import React from 'react';
import './ArrayInfo.css';

const ArrayInfo = ({label,array, sortedIndices}) => {
    if (!array) {
        return null;
    }

    return (
        <div className={"array-info"}>
            <label>{label}</label>
            {
                array.map((item, index) => (
                    <span key={index} className={sortedIndices.includes(index)? "green" : ""}>{item}</span>
                ))
            }
        </div>
    )

}

export default ArrayInfo;