import "./App.css";
import "./AppDark.css";
import React, {Component} from 'react';
import {
    MenuFoldOutlined,
    MenuUnfoldOutlined
} from '@ant-design/icons';
import {Button, Flex, Layout} from 'antd';
import SideBar from "./components/SideBar";
import SortTypes from "./data/SortTypes";
import AppControls from "./components/basic/AppControls/AppControls";
import TopBar from "./components/main/TopBar/TopBar";
import sortTypes from "./data/SortTypes";
import SortInfoTabs from "./components/basic/SortInfoTabs/SortInfoTabs";
import {SortKey} from "./data/SortKey";


const {Header, Content} = Layout;

class App extends Component {
    state = {
        collapsed: false,
        darkMode: false,
        array: [],
        arraySize: 5,
        trace: [],
        key: SortKey.QUICK
    };

    componentDidMount() {
        this.generateRandomArray();
    }

    generateRandomArray = () => {

        console.log('generateRandomArray...');
        function getRandomInt(max) {
            return Math.floor(Math.random() * Math.floor(max)) + 1;
        }

        // Generate an array of length max
        const array = Array(this.state.arraySize)
            .fill(0)
            .map(() => getRandomInt(this.state.arraySize * 5));

        this.setState(
            {
                array,
                trace: []
            },
            this.createTrace
        );
    };

    handleAlgorithmChange = (key) => {
        console.log('handleAlgorithmChange key: ' + key);
        this.setState({key}, this.generateRandomArray);
    };

    handleArraySizeChange = (size) => {
        size = Number(size);
        size = size > 100 ? 100 : size;
        size = size < 0 ? 0 : size;
        this.setState({arraySize: size}, this.generateRandomArray);
    };

    createTrace = () => {
        const numbers = [...this.state.array];
        const sort = sortTypes[this.state.key].algorithm;
        if (sort) {
            const trace = sort(numbers);
            this.setState({trace});
        }
    };

    toggleDarkMode = () => {
        this.setState((prevState) => ({darkMode: !prevState.darkMode}));
    };


    setCollapsed = () => {
        this.setState((prevState) => ({collapsed: !prevState.collapsed}));
    };

    render() {
        console.log('this.state.darkMode: ', this.state.darkMode);
        let classNames = `App main`;
        if (this.state.darkMode) classNames += ` App_dark`;
        const sortType = SortTypes[this.state.key];
        const colorKey = sortType.sortKey;
        const desc = sortType.description;

        return (
            <Flex gap="middle" wrap className={classNames}>
                <Layout>
                    <Layout>
                        <SideBar collapsed={this.state.collapsed} onClick={this.handleAlgorithmChange}></SideBar>
                        <Layout>
                            <Header className="app-bar">
                                <Button
                                    type="text"
                                    icon={this.state.collapsed ? <MenuUnfoldOutlined/> : <MenuFoldOutlined/>}
                                    onClick={() => this.setCollapsed(!this.state.collapsed)}
                                    style={{
                                        fontSize: '16px',
                                        width: 64,
                                        height: 64,
                                    }}
                                />
                                <span className={"app-bar-title"}>ALGO EXPLORER</span>
                            </Header>
                            <Content
                                style={{
                                    margin: '24px 16px',
                                    padding: 24,
                                    minHeight: 280
                                }}
                            >
                                <TopBar>
                                    <AppControls
                                        onGenerateRandomArray={this.generateRandomArray}
                                        algorithm={sortType.algorithm}
                                        onAlgorithmChange={this.handleAlgorithmChange}
                                        arraySize={this.state.arraySize}
                                        onArraySizeChange={this.handleArraySizeChange}
                                        onToggleDarkMode={this.toggleDarkMode}
                                        darkMode={this.state.darkMode}
                                    />
                                </TopBar>
                                <SortInfoTabs desc={desc}
                                              cCode={sortType.implementationCode.c}
                                              cppCode={sortType.implementationCode.cpp}
                                              javaCode={sortType.implementationCode.java}
                                              jsCode={sortType.implementationCode.js}
                                              pythonCode={sortType.implementationCode.python}
                                              array={this.state.array}
                                              trace={this.state.trace}
                                              colorKey={colorKey}
                                              sortKey = {this.state.key}
                                              onGenerateRandomArray={this.generateRandomArray}
                                />

                            </Content>
                        </Layout>
                    </Layout>
                </Layout>
            </Flex>
        );
    }

}

export default App;