import React from 'react';
import './VisualizerControls.css';
import PropTypes from 'prop-types';

import {Button, Tooltip} from 'antd';
import { RetweetOutlined, StepBackwardOutlined, CaretRightOutlined, PauseOutlined, StepForwardOutlined } from '@ant-design/icons';

import { DownOutlined } from '@ant-design/icons';
import { Dropdown, Space, Typography } from 'antd';

function isDisabled(action, disabled = false) {
  return action === undefined || disabled;
}

const VisualizerControls = ({
  // Actions
  onPlay,
  onPause,
  onBackward,
  onForward,
  onRepeat,
  onAdjustSpeed,

  // States
  playing,
  playDisabled,
  pauseDisabled,
  backwardDisabled,
  forwardDisabled,
  repeatDisabled,
  playbackSpeed
}) => {
    const items = [
        {
            key: '0.25x',
            label: '0.25x',
        },
        {
            key: '0.5x',
            label: '0.5x',
        },
        {
            key: '1x',
            label: '1x',
        },
        {
            key: '2x',
            label: '2x',
        },
        {
            key: '4x',
            label: '4x',
        },
    ];
    const onClick = ({ key }) => {
        console.log(`Click on item ${key}`);
        onAdjustSpeed(key);
    };
  return (
    <div className="VisualizerControls">
        <Tooltip title="repeat">
            <Button shape="circle" icon={<RetweetOutlined />} onClick={onRepeat} disabled={isDisabled(onRepeat, repeatDisabled)}/>
        </Tooltip>

        <Tooltip title="backward">
            <Button
            icon={<StepBackwardOutlined />}
            onClick={onBackward}
            disabled={isDisabled(onBackward, backwardDisabled)}
           />
        </Tooltip>

        <Tooltip title={playing ? "pause" : "play"}>
          <Button
            icon={playing ? <PauseOutlined /> : <CaretRightOutlined />}
            onClick={playing ? onPause : onPlay}
            disabled={
              playing
                ? isDisabled(onPause, pauseDisabled)
                : isDisabled(onPlay, playDisabled)
            }
          />
        </Tooltip>

        <Tooltip title="forward">
          <Button
            icon={<StepForwardOutlined />}
            onClick={onForward}
            disabled={isDisabled(onForward, forwardDisabled)}
          />
        </Tooltip>

        <Dropdown
            menu={{
                items,
                onClick,
                selectable: true,
                defaultSelectedKeys: [`${playbackSpeed}x`],
            }}
        >
            <Typography.Link>
                <Space>
                    {`${playbackSpeed}x`}
                    <DownOutlined />
                </Space>
            </Typography.Link>
        </Dropdown>

    </div>
  );
};

VisualizerControls.propTypes = {
  onPlay: PropTypes.func,
  onPause: PropTypes.func,
  onBackward: PropTypes.func,
  onForward: PropTypes.func,
  onRepeat: PropTypes.func,
  onAdjustSpeed: PropTypes.func,

  playing: PropTypes.bool,
  playDisabled: PropTypes.bool,
  pauseDisabled: PropTypes.bool,
  backwardDisabled: PropTypes.bool,
  forwardDisabled: PropTypes.bool,
  repeatDisabled: PropTypes.bool,
  playbackSpeed: PropTypes.number
};

export default VisualizerControls;
