import React from 'react';
import {
  swap,
  newTrace,
  addToTrace,
  lastSorted,
  createKey
} from './helpers';

const SelectionSort = (nums) => {
  // Initial State
  const trace = newTrace(nums);

  // Core Algorithm
  for (let i = 0; i < nums.length - 1; i++) {
    // Internal Loop: Find index of min value
    let minIndex = i;
    for (let j = i + 1; j < nums.length; j++) {
      // Visualize: comparing A[j] to A[minIndex]
      addToTrace(trace, nums, lastSorted(trace), [minIndex, j]);
      if (nums[j] < nums[minIndex]) {
        // Visualize: discovered new minIndex
        addToTrace(trace, nums, lastSorted(trace), [minIndex], [j]);
        minIndex = j;
        // Visualize: reassign new minIndex;
        addToTrace(trace, nums, lastSorted(trace), [minIndex], [j]);
      }
    }

    // Visualize: i'th value to be swapped with min value
    addToTrace(trace, nums, lastSorted(trace), [], [i, minIndex]);

    swap(nums, i, minIndex);

    // Visualize: i'th value has been swapped with min value
    addToTrace(trace, nums, [...lastSorted(trace), i], [], []);
  }

  // Visualize: Final item in the array is sorted
  addToTrace(trace, nums, [...lastSorted(trace), nums.length - 1]);

  return trace;
};

export const SelectionSortKey = createKey('Compare', 'Swap');

export const SelectionSortDesc = {
  title: 'Selection Sort',
  description: (
      <p>
          <a
              href="https://en.wikipedia.org/wiki/Selection_sort"
              target="_blank"
              rel="noopener noreferrer"
          >
              Selection Sort
          </a>{' '}
          is a comparison-based sorting algorithm that works by repeatedly selecting the smallest (or largest) element
          from the unsorted part and moving it to the sorted part.<br/>
          <b>Algorithm Steps:</b>
          <ol>
              <li>
                  Find the smallest element in the array.
              </li>
              <li>
                  Swap it with the first element (placing it in the correct position).
              </li>
              <li>
                  Move to the next position and repeat the process for the remaining elements.
              </li>
              <li>
                  Continue until the entire array is sorted.
              </li>
          </ol>
      </p>
  ),
    worstCase: (
        <span>
      O(n<sup>2</sup>) (always goes through n<sup>2</sup> comparisons)
    </span>
    ),
    avgCase: (
        <span>
      O(n<sup>2</sup>)(always goes through n<sup>2</sup> comparisons)
    </span>
    ),
    bestCase: (
        <span>
      O(n<sup>2</sup>) (always goes through n<sup>2</sup> comparisons)
    </span>
    ),
    space: <span>O(1) (in-place sorting, no extra memory needed)</span>
};

export default SelectionSort;
