import Sider from "antd/es/layout/Sider";
import {Menu} from "antd";
import sortTypes from "../data/SortTypes";
import {SortKey} from "../data/SortKey";

export default function SideBar({collapsed, onClick}) {
    const getSortItems = (sortTypes) => {
        return Object.values(sortTypes).map(sortType => (
            {key: sortType.key, label: sortType.label, icon: sortType.icon}
        ));
     };

    const sortItems = getSortItems(sortTypes);

    const handleClick = (item, key, keyPath, domEvent) => {
        onClick(item.key);
    }

    return (
        <Sider trigger={null} collapsible collapsed={collapsed}>
            <div className="demo-logo-vertical"/>
            <Menu
                theme="dark"
                mode="inline"
                defaultSelectedKeys={[SortKey.QUICK]}
                items={sortItems}
                onClick={handleClick}
            />
        </Sider>
    );
}
