import React from 'react';
import { Tabs } from 'antd';
import './ImplementationTabs.css';

const onChange = (key) => {
    console.log(key);
};

const ImplementationTabs = ({cCode, cppCode, javaCode, jsCode, pythonCode}) => {
    const items = [
        {
            key: '1',
            label: 'C',
            children: <pre><code>{cCode}</code></pre>,
        },
        {
            key: '2',
            label: 'C++',
            children: <pre><code>{cppCode}</code></pre>,
        },
        {
            key: '3',
            label: 'Java',
            children: <pre><code>{javaCode}</code></pre>,
        },
        {
            key: '4',
            label: 'JavaScript',
            children: <pre><code>{jsCode}</code></pre>,
        },
        {
            key: '5',
            label: 'Python',
            children: <pre><code>{pythonCode}</code></pre>,
        },
    ];
    return (
        <Tabs defaultActiveKey="1" items={items} onChange={onChange} />
    );
}
export default ImplementationTabs;

