import React from 'react';
import {newTrace, addToTrace, createKey, lastGroupC, swap} from './helpers';

const InsertionSort = (nums) => {
  // Initial State
  const trace = newTrace(nums);

  // Visualize: first element is in sorted position
  addToTrace(trace, nums, [], [], [], [0]);
  // Core Algorithm
  for (let i = 1; i < nums.length; i++) {
    let value = nums[i];
    let hole = i;

    while (hole > 0 && nums[hole - 1] > value) {

      // Visualize: Compare hole with hole - 1
      addToTrace(trace, nums, [], [hole, hole - 1],[], lastGroupC(trace));

      swap(nums, hole, hole -1);
      //nums[hole] = nums[hole - 1];

      // Visualize: swap element hole and hole -1
      addToTrace(trace, nums, [], [],[hole - 1, hole], lastGroupC(trace));
      hole -= 1;
    }

    nums[hole] = value;

    // Visualize: found the sorted position for element in i position
    addToTrace(trace, nums, [], [], [], [...lastGroupC(trace), i]);
  }

  // Visualize: Mark all elements as sorted
  addToTrace(trace, nums, [...Array(nums.length).keys()]);
  return trace;
};

export const InsertionSortKey = createKey(
  'Compare',
  'Swap',
  'Temporarily sorted'
);
export const InsertionSortDesc = {
  title: 'Insertion Sort',
  description: (
      <div>
          <a
              href="https://en.wikipedia.org/wiki/Insertion_sort"
              target="_blank"
              rel="noopener noreferrer"
          >
              Insertion Sort
          </a>{' '}
          is a simple and efficient comparison-based sorting algorithm that works by building a sorted section of the
          array one element at a time.<br/>
          <b>Algorithm Steps:</b>
          <ol>
              <li>
                  Start with the second element (since the first element is already "sorted").
              </li>
              <li>
                  Compare it with the elements before it and insert it in the correct position.
              </li>
              <li>
                  Repeat for all elements until the array is sorted.
              </li>
          </ol>
      </div>
  ),
    worstCase: (
        <span>
      O(n<sup>2</sup>) (reverse sorted array)
    </span>
    ),
    avgCase: (
        <span>
      O(n<sup>2</sup>)
    </span>
    ),
    bestCase: <span>O(n) (already sorted array)</span>,
    space: <span>O(1) (in-place sorting)</span>
};

export default InsertionSort;
